-- DRAFTS: a rehearsal file (every draft fact and row). Never apply it to production.
-- L08-K3-daily-bank.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   100 rows of the anime daily quiz bank (800 questions), status draft, no date. The owner verifies them, then the daily cron files them.
-- Needs:  L04, 009.
-- Verify: select count(*) from public.quiz_bank where site_id = 'anime';   expect 100
-- Undo:   L08-K3-daily-bank.rollback.sql (refused once a row is scheduled or published).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'quiz_bank' and column_name = 'site_id') then
    raise exception 'L08: quiz_bank.site_id is missing (apply 002a first)';
  end if;
end $o1l$;

do $o1l$ begin
  if not exists (select 1 from public.groups where site_id = 'anime' and slug = 'anime-mix') then
    raise exception 'L08: the anime-mix group is missing (apply L04 first)';
  end if;
end $o1l$;

create temp table _k3_bank (title text, description text, group_slug text, quiz_type text, difficulty text, category text, questions jsonb) on commit drop;

insert into _k3_bank values ('Which Studio Made It? True or False', 'Eight statements pairing anime with their studios: spot the ones that mix them up.', 'anime-mix', 'true_false', 'medium', 'true_false', '[{"question":"Madhouse animated both Death Note and the 2011 Hunter x Hunter anime.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["death-note-anime-staff-005","hunter-x-hunter-second-anime-2011-008"],"source_url":"https://en.wikipedia.org/wiki/Death_Note"},{"question":"Wit Studio animated the first season of the Solo Leveling anime.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["solo-leveling-anime-studio-009"],"source_url":"https://en.wikipedia.org/wiki/Solo_Leveling"},{"question":"Toei Animation produced both the One Piece anime and the Dragon Ball anime.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["one-piece-anime-studio-005","dragon-ball-animation-studio-020"],"source_url":"https://en.wikipedia.org/wiki/One_Piece_(1999_TV_series)"},{"question":"Studio Pierrot animated both Naruto and Cowboy Bebop.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006","cowboy-bebop-studio-director-002"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"MAPPA made the first three seasons of the Attack on Titan anime.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["attack-on-titan-animation-studios-018"],"source_url":"https://en.wikipedia.org/wiki/Attack_on_Titan_(TV_series)"},{"question":"Ufotable produced the Demon Slayer TV anime.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["demon-slayer-studio-director-007"],"source_url":"https://en.wikipedia.org/wiki/Demon_Slayer:_Kimetsu_no_Yaiba_(TV_series)"},{"question":"Doga Kobo animates Oshi no Ko, while Science Saru animates Dandadan.","correct":true,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["oshi-no-ko-anime-studio-staff-007","dandadan-anime-studio-director-008"],"source_url":"https://en.wikipedia.org/wiki/Oshi_no_Ko_(TV_series)"},{"question":"MAPPA animated both Haikyu!! and Chainsaw Man.","correct":false,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["haikyu-anime-season-one-007","chainsaw-man-anime-studio-008"],"source_url":"https://en.wikipedia.org/wiki/Haikyu!!"}]'::jsonb), ('Hidden Leaf Behind the Scenes', 'Eight questions about the people, studio and songs behind the Naruto anime and manga.', 'naruto', 'multiple_choice', 'easy', 'series_specific', '[{"question":"How many episodes does the original Naruto anime run for before Shippuden begins?","options":["100","220","175","366"],"correct":1,"kind":"episode","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"Which studio animated Naruto?","options":["Madhouse","Bones","Studio Pierrot","Wit Studio"],"correct":2,"kind":"production","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-tv-naruto-006"],"source_url":"https://en.wikipedia.org/wiki/Naruto_(TV_series)"},{"question":"In which magazine was the Naruto manga serialized?","options":["Weekly Shonen Magazine","Weekly Shonen Sunday","Weekly Shonen Jump","Monthly Shonen Gangan"],"correct":2,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-serialization-003"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"How many collected volumes did the finished Naruto manga fill?","options":["72","27","60","100"],"correct":0,"kind":"manga","spoiler":{"arc":0,"scope":"both"},"fact_ids":["naruto-manga-size-005"],"source_url":"https://en.wikipedia.org/wiki/Naruto"},{"question":"Who designed the characters for the Naruto anime after the manga author asked for him?","options":["Yusuke Murata","Takeshi Obata","Akira Toriyama","Tetsuya Nishio"],"correct":3,"kind"