update public.quiz_bank b set description = v.description, group_id = g.id, quiz_type = v.quiz_type, difficulty = v.difficulty, category = v.category, questions = v.questions, updated_at = now() from _k3_bank v join public.groups g on g.slug = v.group_slug and g.site_id = 'anime' where b.site_id = 'anime' and b.scheduled_date is null and b.published_quiz_id is null and b.verified_at is null and b.status = 'draft' and md5(lower(btrim(b.title))) = md5(lower(btrim(v.title))) and (b.description, b.group_id, b.quiz_type, b.difficulty, b.category, b.questions) is distinct from (v.description, g.id, v.quiz_type, v.difficulty, v.category, v.questions);

insert into public.quiz_bank (title, description, group_id, quiz_type, difficulty, category, questions, status, site_id) select v.title, v.description, g.id, v.quiz_type, v.difficulty, v.category, v.questions, 'draft', 'anime' from _k3_bank v join public.groups g on g.slug = v.group_slug and g.site_id = 'anime' where not exists (select 1 from public.quiz_bank b where b.site_id = 'anime' and md5(lower(btrim(b.title))) = md5(lower(btrim(v.title))));

delete from public.quiz_bank b where b.site_id = 'anime' and b.scheduled_date is null and b.published_quiz_id is null and b.verified_at is null and b.status = 'draft' and not exists (select 1 from _k3_bank v where md5(lower(btrim(b.title))) = md5(lower(btrim(v.title))));
